using Microsoft.Extensions.Logging;

public class ProductService(
    ILogger<ProductService> logger,
    IProductRepository repository)
{
    public async Task<Product?> GetByIdAsync(int id)
    {
        using (logger.BeginScope(new Dictionary<string, object>
        {
            ["ProductId"] = id,
            ["Operation"] = "GetById"
        }))
        {
            logger.LogInformation("Fetching product {ProductId}", id);

            try
            {
                var product = await repository.GetByIdAsync(id);

                if (product is null)
                {
                    logger.LogWarning("Product {ProductId} not found in database", id);
                    return null;
                }

                logger.LogInformation("Product {ProductId} retrieved: {ProductName}",
                    id, product.Name);
                return product;
            }
            catch (Exception ex)
            {
                logger.LogError(ex,
                    "Failed to fetch product {ProductId}: {ErrorMessage}",
                    id, ex.Message);
                throw;
            }
        }
    }
}

