public class CorrelationIdMiddleware(RequestDelegate next, ILogger<CorrelationIdMiddleware> logger)
{
    public async Task InvokeAsync(HttpContext context)
    {
        // Read or generate a correlation ID
        var correlationId = context.Request.Headers[
            "X-Correlation-ID"].FirstOrDefault()
            ?? Guid.NewGuid().ToString();

        // Add it to the response headers so clients can track requests
        context.Response.Headers["X-Correlation-ID"] = correlationId;

        // Create a scope that includes the correlation ID
        using (logger.BeginScope(new Dictionary<string, object>
        {
            ["CorrelationId"] = correlationId,
            ["Path"] = context.Request.Path
        }))
        {
            logger.LogInformation("Incoming request: {Method} {Path}",
                context.Request.Method,
                context.Request.Path);

            // Continue down the middleware pipeline
            await next(context);

            logger.LogInformation("Response status: {StatusCode}",
                context.Response.StatusCode);
        }
    }
}

