var builder = WebApplication.CreateBuilder(args);

// Configure minimum log levels per category
builder.Logging.ClearProviders();
builder.Logging.AddConsole();

builder.Logging.AddFilter(
    "Microsoft",                         // Microsoft.* categories
    LogLevel.Warning);                    // Only warnings and above

builder.Logging.AddFilter(
    "Microsoft.Hosting.Lifetime",        // Host lifetime logs
    LogLevel.Information);                // Show informational messages

builder.Logging.AddFilter(
    "MyApp",                             // Your application namespace
    LogLevel.Debug);                      // Show debug and above for your code

var app = builder.Build();
app.MapControllers();
app.Run();

